def transform(grid):
    g=[row[:] for row in grid]
    cells=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    # A seed (1 or 3) sends a line toward a 90-degree corner turn; other seed is replicated on the continuation.
    # Based on demo geometries, color 3 extends vertically and color 1 horizontally; bend to opposite endpoint.
    for r,c,v in cells:
        if v==3:
            # extend vertically downward to level of 1, then right to 1
            ones=[(rr,cc) for rr,cc,w in cells if w==1]
            for rr,cc in ones:
                if cc==c:
                    for y in range(min(r,rr)+1,max(r,rr)):
                        if g[y][c]==0:g[y][c]=5
                else:
                    # elbow: vertical at seed column, then horizontal to one; 1 repeated at far corner
                    for y in range(r+1,rr):
                        if g[y][c]==0:g[y][c]=5
                    for x in range(c+1,cc):
                        if g[rr][x]==0:g[rr][x]=5
                    if 0<=r+2<len(g) and 0<=cc+2<len(g[0]): g[r+2][cc+2]=1
        elif v==1:
            # in demo1, extend right two cells, place 1 one row above endpoint
            # only when associated with 3 absent
            if not any(w==3 for _,_,w in cells):
                for x in range(c+1,min(c+3,len(g[0]))):
                    if g[r][x]==0:g[r][x]=5
                if r>0 and c+2<len(g[0]):g[r-1][c+2]=1
    # 2 objects: fill horizontal to left boundary pattern
    for r,c,v in cells:
        if v==2:
            for x in range(1,c):
                if g[r][x]==0:g[r][x]=5
    return g
