def transform(grid):
    g=[r[:] for r in grid]
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    # Two-color endpoints define a set of perpendicular rays; retain given markers,
    # extend 2 horizontally toward the nearest other marker's column with 5,
    # extend 3 vertically toward the nearest 1 with 5, and extend 1 diagonally away
    # from the 2/3 assembly in color 4 when a diagonal marker (6) is present.
    by={v:(r,c) for r,c,v in pts}
    if 2 in by:
        r,c=by[2]
        # observed 2 is the corner/center of a horizontal 5-bar reaching neighbor markers on both sides
        for rr,cc,v in pts:
            if rr==r and v!=2:
                for x in range(min(c,cc)+1,max(c,cc)):
                    if g[r][x]==0:g[r][x]=5
    if 3 in by and 1 in by:
        r3,c3=by[3];r1,c1=by[1]
        # connect 3 toward row of 1 with vertical 5; then horizontal toward 1
        for y in range(min(r3,r1)+1,max(r3,r1)):
            if g[y][c3]==0:g[y][c3]=5
        if r1==r3:
            for x in range(min(c1,c3)+1,max(c1,c3)):
                if g[r1][x]==0:g[r1][x]=5
    if 6 in by and 3 in by:
        r,c=by[6]
        # 6 acts as origin of diagonal 4 ray toward bottom-left, as the 2-marker in pair 3 does
        for k in range(1,min(len(g)-r,c+1)):
            if g[r+k][c-k]==0:g[r+k][c-k]=4
    return g
