def transform(grid):
    g=[row[:] for row in grid]
    n,m=len(g),len(g[0])
    pts={(r,c):v for r,row in enumerate(grid) for c,v in enumerate(row) if v}
    # 2 creates a horizontal segment of length 5, with 2s as endpoints.
    for (r,c),v in list(pts.items()):
        if v==2:
            left=max(1,c-4); right=min(m-2,c+4)
            for x in range(left,right+1):
                if g[r][x]==0:g[r][x]=5
            g[r][left]=g[r][right]=2
    # 1 continues rightward as a short 5-line, with a second 1 one row above its end.
    for (r,c),v in list(pts.items()):
        if v==1:
            for x in range(c+1,min(c+3,m)):
                if g[r][x]==0:g[r][x]=5
            if r>0 and c+2<m:g[r-1][c+2]=1
    # 3 continues vertically downward for two cells with 5 between copies.
    for (r,c),v in list(pts.items()):
        if v==3:
            for y in range(r+1,min(r+3,n)):
                if g[y][c]==0:g[y][c]=5
            if r+3<n:g[r+3][c]=3
    # 6 draws a diagonal of 4s down-left to the grid boundary.
    for (r,c),v in list(pts.items()):
        if v==6:
            for k in range(1,min(n-r,c+1)):
                if g[r+k][c-k]==0:g[r+k][c-k]=4
    return g
