def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    points=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    twos=[(r,c) for r,c,v in points if v==2]
    sixes=[(r,c) for r,c,v in points if v==6]
    # Color 1: copy at (-1,+2), linked horizontally by 5.
    for r,c,v in points:
        if v==1 and r-1>=0 and c+2<w:
            out[r-1][c+2]=1
            for x in range(c+1,c+3):
                if out[r][x]==0: out[r][x]=5
        elif v==2 and c-4>=0:
            out[r][c-4]=2
            for x in range(c-3,c):
                if out[r][x]==0: out[r][x]=5
        elif v==3 and r+3<h:
            out[r+3][c]=3
            for y in range(r+1,r+3):
                if out[y][c]==0: out[y][c]=5
        elif v==6 and r-6>=0:
            out[r-6][c]=6
            for y in range(r-5,r):
                if out[y][c]==0: out[y][c]=5
    # A 2-horizontal and 6-vertical connector crossing becomes 4; continue diagonally down-left.
    for r2,c2 in twos:
        for r6,c6 in sixes:
            cross=(r2,c6)
            if c2-4<=c6<=c2 and r6<=r2 and r6-6<=r2:
                x,y=cross[1],cross[0]
                out[y][x]=4
                k=1
                while y+k<h and x-k>=0:
                    out[y+k][x-k]=4
                    k+=1
    return out
