def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    for r,c,v in pts:
        if v==1 and r>0 and c+2<w:
            out[r-1][c+2]=1
            for x in (c+1,c+2): out[r][x]=5
        elif v==2 and c>=4:
            left=c-4
            out[r][left]=2
            for x in range(left+1,c): out[r][x]=5
        elif v==3 and r+3<h:
            out[r+3][c]=3
            for y in (r+1,r+2): out[y][c]=5
        elif v==6 and r>=6:
            out[r-6][c]=6
            for y in range(r-5,r): out[y][c]=5
    twos=[(r,c) for r,c,v in pts if v==2]
    sixes=[(r,c) for r,c,v in pts if v==6]
    for r,c in twos:
        if c>=4:
            mid=c-2
            if any(rr>r and cc==mid for rr,cc in sixes):
                out[r][mid]=4
                for k in range(1,min(h-r,mid+1)):
                    out[r+k][mid-k]=4
    return out
